```python
def lcm(a, b):
    """Compute the least common multiple of two positive integers."""
    if a == 0 or b == 0:
        return 0
    a_abs, b_abs = abs(a), abs(b)
    if a_abs < b_abs:
        a_abs, b_abs = b_abs, a_abs
    for i in range(a_abs, a_abs * b_abs, a_abs):
        if i % b_abs == 0:
            return i
    return a_abs * b_abs


def lcm_all(nums):
    """Least common multiple of a list of positive integers."""
    if not nums:
        return 0
    out = 1
    for n in nums:
        out = lcm(out, n)
    return out
