def test_basic_calculation():
    """$20.00 order with 7.25% tax should be $21.45"""
    assert checkout.total_with_tax(20.00, "California") == 21.45

def test_zero_subtotal():
    """Zero subtotal should remain zero"""
    assert checkout.total_with_tax(0.00, "California") == 0.00

def test_no_tax():
    """If rate is 0, total equals subtotal"""
    assert checkout.total_with_tax(100.00, "NoTax") == 100.00

def test_rounding():
    """Rounding to 2 decimal places"""
    assert checkout.total_with_tax(10.00, "California") == 10.73

def test_large_amount():
    """Large amounts should round correctly"""
    assert checkout.total_with_tax(1000.00, "California") == 1072.50

def test_fractional_subtotal():
    """Fractional subtotals should round correctly"""
    assert checkout.total_with_tax(10.50, "California") == 11.34

def test_negative_subtotal():
    """Negative subtotals should round correctly"""
    assert checkout.total_with_tax(-10.00, "California") == -10.73

def test_rate_import():
    """rate function should be importable from taxes"""
    assert callable(taxes.rate)

