import unittest
from unittest.mock import patch, MagicMock
from alerts import too_hot, HOT_C


class TestTooHot(unittest.TestCase):
    """Tests for the too_hot function in alerts.py."""

    @patch('alerts.read')
    def test_not_hot_at_threshold(self, mock_read):
        """At exactly 30°C, should NOT trigger an alert."""
        mock_read.return_value = 30.0
        self.assertFalse(too_hot("sensor1"))

    @patch('alerts.read')
    def test_hot_above_threshold(self, mock_read):
        """Above 30°C should trigger an alert."""
        mock_read.return_value = 30.1
        self.assertTrue(too_hot("sensor1"))

    @patch('alerts.read')
    def test_not_hot_below_threshold(self, mock_read):
        """Below 30°C should NOT trigger an alert."""
        mock_read.return_value = 29.9
        self.assertFalse(too_hot("sensor1"))

    @patch('alerts.read')
    def test_hot_far_above(self, mock_read):
        """Far above 30°C should trigger an alert."""
        mock_read.return_value = 100.0
        self.assertTrue(too_hot("sensor1"))

    @patch('alerts.read')
    def test_not_hot_at_zero(self, mock_read):
        """Zero degrees should NOT trigger an alert."""
        mock_read.return_value = 0.0
        self.assertFalse(too_hot("sensor1"))

    @patch('alerts.read')
    def test_not_hot_at_negative(self, mock_read):
        """Negative temperature should NOT trigger an alert."""
        mock_read.return_value = -5.0
        self.assertFalse(too_hot("sensor1"))

    @patch('alerts.read')
    def test_hot_at_30_plus_epsilon(self, mock_read):
        """30°C + small epsilon should trigger an alert."""
        mock_read.return_value = 30.0001
        self.assertTrue(too_hot("sensor1"))

    @patch('alerts.read')
    def test_not_hot_at_30_minus_epsilon(self, mock_read):
        """30°C - small epsilon should NOT trigger an alert."""
        mock_read.return_value = 29.9999
        self.assertFalse(too_hot("sensor1"))


if __name__ == '__main__':
    unittest.main()

import plugins
import registry


def test_case_insensitive_lookup():
    """Plugin names are case-insensitive."""
    registry.register("Resize", lambda: "resized")
    assert plugins.run("resize") == "resized"
    assert plugins.run("RESIZE") == "resized"
    assert plugins.run("Resize") == "resized"


def test_keyerror_for_missing_plugin():
    """Missing plugin raises KeyError."""
    try:
        plugins.run("NonExistent")
        assert False, "Expected KeyError"
    except KeyError as e:
        assert "no plugin" in str(e)


def test_args_passed_through():
    """Arguments are passed through to the plugin."""
    registry.register("Add", lambda a, b: a + b)
    assert plugins.run("Add", 3, 4) == 7


def test_no_args_plugin():
    """Plugin with no extra args works."""
    registry.register("Hello", lambda: "hello")
    assert plugins.run("Hello") == "hello"


def test_multiple_plugins_registered():
    """Multiple plugins can be registered and run independently."""
    registry.register("A", lambda: "a")
    registry.register("B", lambda: "b")
    assert plugins.run("A") == "a"
    assert plugins.run("B") == "b"


def test_keyerror_message_contains_name():
    """KeyError message includes the requested plugin name."""
    try:
        plugins.run("Missing")
        assert False
    except KeyError as e:
        assert "Missing" in str(e)


def test_lookup_returns_none_for_missing():
    """registry.lookup returns None for unregistered plugin."""
    assert registry.lookup("Unregistered") is None


def test_run_raises_on_none_lookup():
    """run raises KeyError when lookup returns None."""
    try:
        plugins.run("Unregistered")
        assert False
    except KeyError:
        pass

