def parse_version(text):
    """'1.2.3' -> (1, 2, 3)"""
    if text is None:
        return None
    if not isinstance(text, str):
        return None

    text = text.strip()
    if not text:
        return None

    # Remove leading 'v' if present
    if text.startswith('v') or text.startswith('V'):
        text = text[1:]

    # Split by '.'
    parts = text.split('.')

    # Check if we have exactly 3 parts
    if len(parts) != 3:
        return None

    # Check if all parts are valid integers (no non-numeric characters, no leading zeros? The spec doesn't mention leading zeros as invalid, but '1.x' is malformed)
    result = []
    for p in parts:
        try:
            val = int(p)
            result.append(val)
        except ValueError:
            return None

    return tuple(result)
