import os
from uploads import user_file


def test_simple_name():
    """A simple name should be joined and normalized inside base."""
    result = user_file("/uploads", "file.txt")
    assert result == "/uploads/file.txt"


def test_subdir_name():
    """A name with a subdirectory should be joined and normalized."""
    result = user_file("/uploads", "sub/file.txt")
    assert result == "/uploads/sub/file.txt"


def test_parent_escape_refused():
    """A name that escapes the base directory should raise ValueError."""
    try:
        user_file("/uploads", "../x")
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_double_parent_escape_refused():
    """A name that escapes the base directory via '..' should raise ValueError."""
    try:
        user_file("/uploads", "sub/../../x")
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_absolute_path_refused():
    """An absolute path should raise ValueError."""
    try:
        user_file("/uploads", "/x")
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_empty_name():
    """An empty name should return just the base path."""
    result = user_file("/uploads", "")
    assert result == "/uploads"


def test_trailing_slash():
    """A name with a trailing slash should be normalized."""
    result = user_file("/uploads", "file.txt/")
    assert result == "/uploads/file.txt"


def test_dotdot_in_middle():
    """A name with '..' in the middle that escapes base should raise ValueError."""
    try:
        user_file("/uploads", "a/../b")
        assert False, "Expected ValueError"
    except ValueError:
