import unittest
from solution import signature


class TestSignature(unittest.TestCase):
    def test_basic_case(self):
        """signature('Ada Lovelace', 'Engineer') must be 'A.L. (Engineer)'."""
        self.assertEqual(signature('Ada Lovelace', 'Engineer'), 'A.L. (Engineer)')

    def test_single_word_name(self):
        """Single word name should produce a single initial."""
        self.assertEqual(signature('Ada', 'Engineer'), 'A. (Engineer)')

    def test_three_word_name(self):
        """Three word name should produce three initials."""
        self.assertEqual(signature('Ada Lovelace Foo', 'Engineer'), 'A.L.F. (Engineer)')

    def test_empty_role(self):
        """Empty role should still work with the format."""
        self.assertEqual(signature('Ada Lovelace', ''), 'A.L. ()')

    def test_empty_name(self):
        """Empty name should produce empty initials."""
        self.assertEqual(signature('', 'Engineer'), ' ()')

    def test_multiple_spaces(self):
        """Multiple spaces between words should be handled."""
        self.assertEqual(signature('Ada   Lovelace', 'Engineer'), 'A.L. (Engineer)')

    def test_special_characters_in_name(self):
        """Special characters in name should not affect initials."""
        self.assertEqual(signature('Ada-Lov&Lace', 'Engineer'), 'A.L. (Engineer)')

    def test_role_with_spaces(self):
        """Role with spaces should be included as-is."""
        self.assertEqual(signature('Ada Lovelace', 'Engineer (Main)'), 'A.L. (Engineer (Main))')

